/****************Start hamburger__line****************/
.hamburger__line {
    background: #f6ba42;
    height: 0.25rem;
    width: 1.7rem;
    display: block;
    margin: 4px auto 0;
    transition: all 0.2s;
    z-index: 3;
}

.hamburger__line-active {
    background: white;
    position: inherit;
    z-index: 999999999;
}

.hamburger__line-active:nth-child(1) {
    transform: rotate(45deg);
    position: relative;
}

.hamburger__line-active:nth-child(2) {
    display: none;
}

.hamburger__line-active:nth-child(3) {
    transform: rotate(-45deg);
    top: -10px;
    position: relative;
}

